import random

class MarkovChain:
    def __init__(self):
        self.chain = {}

    def train(self, text):
        words = text.split()
        for i in range(len(words) - 1):
            current_word = words[i]
            next_word = words[i+1]
            if current_word not in self.chain:
                self.chain[current_word] = []
            self.chain[current_word].append(next_word)

    def generate(self, length=100):
        if not self.chain:
            return ""

        current_word = random.choice(list(self.chain.keys()))
        result = [current_word]

        for _ in range(length - 1):
            if current_word in self.chain and self.chain[current_word]:
                next_word = random.choice(self.chain[current_word])
                result.append(next_word)
                current_word = next_word
            else:
                break

        return ' '.join(result)

